datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

enum Role {
  ADMIN
  MENTOR
  ASSISTANT
  STUDENT
}

enum Action {
  GET
  POST
  PUT
  PATCH
  DELETE
}

enum CourseLevel {
  BEGINNER
  PRE_INTERMEDIATE
  INTERMEDIATE
  UPPER_INTERMEDIATE
  ADVANCED
}

enum PaidVia {
  PAYME
  CLICK
  CASH
}

enum HomeworkSubStatus {
  PENDING
  APPROVED
  REJECTED
}

enum ExamAnswer {
  A
  B
  C
  D
}

model User {
  id                 String               @id @default(uuid())
  fullName           String?
  email              String               @unique
  password           String
  image              String?
  userDeleted        Boolean              @default(false)
  role               Role                 @default(STUDENT)
  mentorProfile      MentorProfile?
